steps.ns_rules:
table inet dawnline
delete table inet dawnline
table inet dawnline {
	flowtable ft {
		hook ingress priority 0;
		devices = { "dlx1", "dll1" };
	}
	chain nat_pre {
		type nat hook prerouting priority dstnat; policy accept;
		iifname "dlx1" ip daddr 192.168.77.254 meta l4proto { tcp, udp } th dport 53 dnat ip to 192.168.77.1:53
	}
	chain nat_post {
		type nat hook postrouting priority srcnat; policy accept;
		oifname "dll1" masquerade
	}
	chain filter_forward {
		type filter hook forward priority filter; policy drop;
		ct state established meta l4proto { tcp, udp } flow add @ft
		ct state established,related accept
		iifname "dlx1" oifname "dll1" accept
	}
	chain filter_input {
		type filter hook input priority filter; policy drop;
		ct state established,related accept
		iifname "lo" accept
		icmp type echo-request accept
		iifname "dlx1" meta l4proto { tcp, udp } th dport 53 accept
	}
}

